Music Folderimport Cocoa

enum IconSetter {
    @discardableResult
    static func setIcon(imagePath: String, targetPath: String) -> Bool {
        guard let original = NSImage(contentsOfFile: imagePath) else {
            return false
        }
        let icon = resized(original, to: 512)
        return NSWorkspace.shared.setIcon(icon, forFile: targetPath, options: [])
    }

    /// Scales an image to fit within maxDim x maxDim, preserving aspect ratio.
    private static func resized(_ image: NSImage, to maxDim: CGFloat) -> NSImage {
        let size = image.size
        guard size.width > maxDim || size.height > maxDim else { return image }
        let scale = min(maxDim / size.width, maxDim / size.height)
        let newSize = NSSize(width: size.width * scale, height: size.height * scale)
        let newImage = NSImage(size: newSize)
        newImage.lockFocus()
        image.draw(in: NSRect(origin: .zero, size: newSize),
                   from: NSRect(origin: .zero, size: size),
                   operation: .copy,
                   fraction: 1.0)
        newImage.unlockFocus()
        return newImage
    }

    @discardableResult
    static func removeIcon(targetPath: String) -> Bool {
        return NSWorkspace.shared.setIcon(nil, forFile: targetPath, options: [])
    }
}
